insert into public.categories (slug, name, description, cover, sort) values
  ('scented-candles', 'Scented candles', 'One candle, one clear mood. Soy wax and fragrance, poured in small batches.', 'desi-gulab', 0),
  ('jar-candles', 'Jar candles', 'Burn it down, wash it out, keep the jar. Even-burning glass candles.', 'oud-majlis', 1),
  ('floral-fragrances', 'Floral fragrances', 'Rose, motia and raat ki rani. A garden in bloom, any month of the year.', 'motia-nights', 2),
  ('decorative-candles', 'Decorative candles', 'Pillars and tapers that dress a table before they are even lit.', 'twisted-taper-pair', 3),
  ('gift-sets', 'Gift sets', 'Boxed, ribboned and ready to give, with your note written by hand.', 'the-evening-trio', 4),
  ('seasonal-collections', 'Seasonal collections', 'Here for a season, then gone. Limited pours for winter, Ramadan and Eid.', 'winter-bonfire', 5)
insert into public.products (id, slug, name, tagline, description, categories, tags, fragrance, fragrance_family, notes, wax_type, colour, dimensions, ingredients, art, images, colours, discount_percent, sold, featured, best_seller, is_new, active, created_at) values
  ('p01', 'desi-gulab', 'Desi Gulab', 'A fresh rose garland, with a thread of saffron', 'The smell of a rose garland an hour after it is strung. Deep red desi gulab sits over warm saffron and a quiet base of oud, so the room smells of flowers without turning sweet.', array['scented-candles', 'jar-candles', 'floral-fragrances']::text[], array['rose', 'saffron', 'bestseller']::text[], 'Rose and saffron', 'Floral', '{"top":"Saffron, pink pepper","middle":"Desi gulab","base":"Oud, musk"}'::jsonb, 'Soy wax', 'Blush', '8 cm wide, 9 cm tall', 'Soy wax, cotton wick, fragrance oil', '{"shape":"jar","wax":"#E7C1B4","vessel":"#F3E7D8","bg":"#F0DCD2"}'::jsonb, array['1777107857794-0ae7cfb2475f', '1555178738-465e12b1bfc3']::text[], '[]'::jsonb, null, 412, true, true, false, true, '2026-03-02'),
  ('p02', 'chai-and-cardamom', 'Chai & Cardamom', 'The first cup of the day, without the wait', 'Black tea, crushed elaichi and warm milk. It smells like the first cup of the day, made slowly, with the window open.', array['scented-candles', 'jar-candles']::text[], array['chai', 'spice', 'winter']::text[], 'Black tea and cardamom', 'Gourmand', '{"top":"Cardamom, ginger","middle":"Black tea, clove","base":"Steamed milk, vanilla"}'::jsonb, 'Soy wax', 'Milk tea', '8 cm wide, 9 cm tall', 'Soy wax, cotton wick, fragrance oil', '{"shape":"jar","wax":"#D9B88F","vessel":"#B9824A","bg":"#EBD9BD"}'::jsonb, array['1738597966280-30cef2e4ba86', '1610410863509-aa6ee0b12d76']::text[], '[]'::jsonb, 15, 366, false, true, false, true, '2026-04-11'),
  ('p03', 'motia-nights', 'Motia Nights', 'Jasmine, picked after dark', 'Fresh motia buds, green stems and a trace of sandal. Light it in the evening and it fills a bedroom in twenty minutes.', array['scented-candles', 'jar-candles', 'floral-fragrances']::text[], array['jasmine', 'motia', 'new']::text[], 'Jasmine', 'Floral', '{"top":"Green leaf, bergamot","middle":"Motia, raat ki rani","base":"Sandalwood"}'::jsonb, 'Soy wax', 'Ivory', '8 cm wide, 9 cm tall', 'Soy wax, cotton wick, fragrance oil', '{"shape":"jar","wax":"#F4EBD6","vessel":"#DDE3CF","bg":"#E4E8D6"}'::jsonb, array['1612179543058-ab74d388e0ce', '1585641689080-2e530457803b']::text[], '[]'::jsonb, null, 94, true, false, true, true, '2026-10-20'),
  ('p04', 'oud-majlis', 'Oud Majlis', 'For the room that is expecting guests', 'Our richest pour. Dark oud, amber resin and a little leather, for a drawing room that is expecting guests.', array['scented-candles', 'jar-candles']::text[], array['oud', 'amber', 'premium']::text[], 'Oud and amber', 'Woody', '{"top":"Black pepper, incense","middle":"Oud, leather","base":"Amber resin, patchouli"}'::jsonb, 'Soy and coconut wax', 'Charcoal', '9 cm wide, 10 cm tall', 'Soy and coconut wax, wooden wick, fragrance oil', '{"shape":"jar","wax":"#5A4034","vessel":"#2E1F17","bg":"#D8C4A8"}'::jsonb, array['1643717714079-b5c739c1e420', '1760804876364-33c5063a7540']::text[], '[]'::jsonb, null, 203, true, true, false, true, '2026-01-18'),
  ('p05', 'monsoon-earth', 'Monsoon Earth', 'The first rain on dry earth', 'Wet clay, vetiver and cold air. The smell that makes everyone walk to the window in July, kept in a travel tin.', array['scented-candles']::text[], array['petrichor', 'vetiver', 'travel tin']::text[], 'Petrichor and vetiver', 'Earthy', '{"top":"Rain, ozone","middle":"Wet clay","base":"Vetiver, moss"}'::jsonb, 'Soy wax', 'Clay', '7.5 cm wide, 4.5 cm tall', 'Soy wax, cotton wick, fragrance oil', '{"shape":"tin","wax":"#C9B8A0","vessel":"#7B6A58","bg":"#DDD6C6"}'::jsonb, array['1711563220049-65298a6a4ecf', '1641793687826-f44f5e1a9e1a']::text[], '[]'::jsonb, null, 251, false, false, false, true, '2026-06-28'),
  ('p06', 'kinnow-grove', 'Kinnow Grove', 'Winter citrus, peel and all', 'Bright kinnow peel, a squeeze of juice and green leaves. Sharp and clean, good for kitchens and for mornings.', array['scented-candles']::text[], array['citrus', 'kinnow', 'travel tin']::text[], 'Kinnow and green leaf', 'Fresh', '{"top":"Kinnow peel, lemon","middle":"Orange blossom","base":"Green leaf, cedar"}'::jsonb, 'Soy wax', 'Marigold', '7.5 cm wide, 4.5 cm tall', 'Soy wax, cotton wick, fragrance oil', '{"shape":"tin","wax":"#F0C27A","vessel":"#C98A3A","bg":"#F3E2BF"}'::jsonb, array['1785284262850-96c48a9cb1b4', '1609536335343-4cc00bbd23ef']::text[], '[]'::jsonb, 20, 188, false, false, false, true, '2026-05-09'),
  ('p07', 'sandal-and-smoke', 'Sandal & Smoke', 'Calm in a jar, with a curl of incense', 'Creamy sandalwood and the last minute of an incense stick. Calm, dry and slightly sweet.', array['scented-candles', 'jar-candles']::text[], array['sandalwood', 'incense']::text[], 'Sandalwood and incense', 'Woody', '{"top":"Cardamom","middle":"Sandalwood, incense","base":"Cedar, tonka"}'::jsonb, 'Soy wax', 'Sand', '8 cm wide, 9 cm tall', 'Soy wax, cotton wick, fragrance oil', '{"shape":"jar","wax":"#DCC9A8","vessel":"#EDE3D0","bg":"#E6DAC2"}'::jsonb, array['1617041261380-15cf80c39f26', '1572726729207-a78d6feb18d7']::text[], '[]'::jsonb, null, 176, false, false, false, true, '2026-02-14'),
  ('p08', 'vanilla-kheer', 'Vanilla Kheer', 'Dessert, minus the dishes', 'Thick, warm and comforting. Vanilla pod, reduced milk and a pinch of cardamom, like kheer cooling in a clay bowl.', array['scented-candles', 'jar-candles']::text[], array['vanilla', 'dessert']::text[], 'Vanilla and milk', 'Gourmand', '{"top":"Cardamom, almond","middle":"Reduced milk, rice","base":"Vanilla pod"}'::jsonb, 'Soy wax', 'Cream', '8 cm wide, 9 cm tall', 'Soy wax, cotton wick, fragrance oil', '{"shape":"jar","wax":"#F3E6C8","vessel":"#F6EEDD","bg":"#EFE4CC"}'::jsonb, array['1604172083143-081d302edb4d', '1604160526046-937cf7465b83']::text[], '[]'::jsonb, null, 297, false, false, false, true, '2026-03-25'),
  ('p09', 'amber-pillar', 'Amber Pillar', 'The pillar that glows from the inside', 'A hand-poured pillar that hollows as it burns, so the flame lights the walls of the candle. Lightly scented with amber.', array['decorative-candles', 'scented-candles']::text[], array['pillar', 'amber', 'table']::text[], 'Soft amber', 'Woody', null, 'Palm-free pillar blend', 'Caramel', '7 cm wide', 'Pillar wax blend, cotton wick, fragrance oil', '{"shape":"pillar","wax":"#C98E52","vessel":"#C98E52","bg":"#EAD8BC"}'::jsonb, array['1636714528228-f469eefb3eef', '1640095889747-2090ee12fa7d']::text[], '[{"name":"Amber","hex":"#C98E52"},{"name":"Ivory","hex":"#F4EEE1"},{"name":"Sage","hex":"#A8B59A"}]'::jsonb, null, 121, false, false, false, true, '2026-07-07'),
  ('p10', 'twisted-taper-pair', 'Twisted Taper Pair', 'Dinner looks better by candlelight', 'A pair of unscented tapers for the dinner table, so nothing competes with the food. They fit any standard candlestick.', array['decorative-candles']::text[], array['taper', 'unscented', 'dinner']::text[], null, 'Unscented', null, 'Beeswax blend', null, '2.2 cm wide, 25 cm tall', 'Beeswax blend, cotton wick', '{"shape":"taper","wax":"#EFE3CB","vessel":"#A9692F","bg":"#E3D5BE"}'::jsonb, array['1640085461451-e3dc47415dd1', '1702913288156-f55d0f64f7b7']::text[], '[]'::jsonb, null, 88, false, false, true, true, '2026-09-15'),
  ('p11', 'the-evening-trio', 'The Evening Trio', 'Three scents. One very good gift.', 'Desi Gulab, Sandal & Smoke and Chai & Cardamom in 90 g votives. A good way to find your favourite, or to give all three away.', array['gift-sets', 'scented-candles']::text[], array['gift', 'votive', 'sampler']::text[], 'Rose, sandalwood and chai', 'Floral', null, 'Soy wax', null, 'Box 24 × 9 × 8 cm', 'Soy wax, cotton wick, fragrance oil', '{"shape":"set","wax":"#E7C1B4","vessel":"#F3E7D8","bg":"#E9DCC8"}'::jsonb, array['1638460392258-27e2283cfafb', '1643122966676-29e8597257f7', '1602607203559-d38903b80507']::text[], '[]'::jsonb, 10, 164, true, false, false, true, '2026-08-01'),
  ('p12', 'eid-gifting-box', 'Eid Gifting Box', 'Eid, wrapped and ready', 'Oud Majlis and Desi Gulab with a brass-tipped matchbox and an Eid card we write by hand. Ships in a linen-wrapped box.', array['gift-sets', 'seasonal-collections']::text[], array['gift', 'eid', 'limited']::text[], 'Oud and rose', 'Woody', null, 'Soy wax', null, 'Box 26 × 20 × 11 cm', 'Soy wax, cotton and wooden wicks, fragrance oil', '{"shape":"set","wax":"#5A4034","vessel":"#C98A3A","bg":"#E2CFAE"}'::jsonb, array['1784292877311-fd49ac66ddc8', '1760804876250-605a3cd49ede', '1760804876257-f073f77f2bcf']::text[], '[]'::jsonb, null, 73, false, false, false, true, '2026-02-26'),
  ('p13', 'winter-bonfire', 'Winter Bonfire', 'A Quetta winter night, bottled', 'A December night in Quetta: woodsmoke on cold air, roasted moongphali and a heavy wool shawl. Poured once a year, only for winter.', array['seasonal-collections', 'scented-candles', 'jar-candles']::text[], array['winter', 'smoke', 'limited', 'new']::text[], 'Woodsmoke and roasted nuts', 'Woody', '{"top":"Cold air, clove","middle":"Burning wood","base":"Roasted peanut, vanilla"}'::jsonb, 'Soy wax', 'Ember', '8 cm wide, 9 cm tall', 'Soy wax, wooden wick, fragrance oil', '{"shape":"jar","wax":"#C9793C","vessel":"#6A3F26","bg":"#E8CDAA"}'::jsonb, array['1667988152051-c689a7905701', '1528351655744-27cc30462816']::text[], '[]'::jsonb, null, 58, true, false, true, true, '2026-11-01')
