insert into public.site_content (key, value) values
  ('hero', '[{"image":"https://images.unsplash.com/photo-1668954443518-34de30690425?auto=format&fit=crop&w=2000&q=75","alt":"A lit amber jar candle glowing in a dark room","position":"60% center","kicker":"Hand-poured in Quetta","title":["Light up the","quiet hours."],"text":"Slow-burning soy candles in scents that feel like home. Strike a match and let the evening begin.","primary":{"label":"Shop all candles","href":"/shop"},"secondary":{"label":"Meet Winter Bonfire","href":"/products/winter-bonfire"}},{"image":"https://images.unsplash.com/photo-1544472991-1324437fe348?auto=format&fit=crop&w=2000&q=75","alt":"A lit pillar candle in front of soft golden lights","position":"70% center","kicker":"Winter Glow Sale, ends 30 November","title":["Long nights,","lower prices."],"text":"Up to 20% off the candles made for winter. Chai, citrus and a little woodsmoke.","primary":{"label":"Shop the sale","href":"/shop?sale=1"},"secondary":{"label":"See best sellers","href":"/shop?sort=best-selling"}},{"image":"https://images.unsplash.com/photo-1602523961358-f9f03dd557db?auto=format&fit=crop&w=2000&q=75","alt":"Three lit white candles on a dark surface","position":"50% center","kicker":"Gift sets, boxed and ribboned","title":["Give them","the glow."],"text":"Three scents in one keepsake box, with your note written by hand. The gift that actually gets used.","primary":{"label":"Shop gift sets","href":"/collections/gift-sets"},"secondary":{"label":"View The Evening Trio","href":"/products/the-evening-trio"}}]'::jsonb),
  ('faqs', '[{"q":"How do I pay?","a":"Every order is paid by Easypaisa. At checkout we show our Easypaisa number and the exact amount, delivery included. Send it from your Easypaisa app or any bank app, then add the transaction ID and a screenshot. We check the payment and confirm your order, usually within a few hours."},{"q":"How long does delivery take?","a":"Orders leave our studio within 2 working days. Delivery takes 2 to 4 working days in major cities and up to 6 elsewhere."},{"q":"How much is delivery?","a":"Delivery is Rs. 500 within Quetta and Rs. 250 to other cities in Pakistan. It is free on orders over Rs. 5,000. Checkout shows the exact fee for your city."},{"q":"How do I track my order?","a":"When your order is dispatched we email you the courier name and tracking ID. Open that email, copy the tracking ID and paste it on the courier’s official website. Our Track order page links to every courier we use."},{"q":"Can I cancel or change my order?","a":"Yes, until it is dispatched. Message us on WhatsApp with your order number and we will sort it out."},{"q":"My candle arrived damaged. What now?","a":"Send us a photo on WhatsApp within 48 hours of delivery. We will replace it or refund you, whichever you prefer."},{"q":"What wax do you use?","a":"Most of our candles are soy wax with cotton or wooden wicks. Pillars and tapers use firmer blends so they hold their shape. Each product page lists exactly what is inside."},{"q":"Do you take custom or bulk orders?","a":"We do, for weddings, corporate gifts and Eid. Tell us the quantity and date on WhatsApp and we will send a quote."}]'::jsonb),
  ('policies', '{"shipping":{"title":"Shipping policy","intro":"We deliver across Pakistan through trusted courier companies.","sections":[{"heading":"Delivery charges","body":["Delivery is Rs. 500 per order within Quetta and Rs. 250 to every other city in Pakistan.","Orders over Rs. 5,000 are delivered free."]},{"heading":"Delivery time","body":["We confirm every order by phone or WhatsApp before packing it.","Orders are dispatched within 2 working days of confirmation and usually arrive 2 to 4 working days after that."]},{"heading":"Tracking","body":["Once your order is dispatched we send you the courier name and tracking number. Use that number on the courier’s official website to follow your parcel."]}]},"returns":{"title":"Returns and refunds","intro":"We want you to be happy with every candle you light.","sections":[{"heading":"Damaged or wrong items","body":["If your order arrives damaged or incorrect, send us a photo on WhatsApp within 48 hours of delivery.","We will send a replacement at no cost, or refund the amount you paid."]},{"heading":"Change of mind","body":["Unused candles in their original packaging can be returned within 7 days. Return delivery is paid by the customer.","Candles that have been lit cannot be returned."]},{"heading":"Refunds","body":["Refunds are sent by bank transfer, JazzCash or Easypaisa within 5 working days of us receiving the return."]}]},"privacy":{"title":"Privacy policy","intro":"We collect only what we need to deliver your order.","sections":[{"heading":"What we collect","body":["Your name, phone number and delivery address, and your email address if you choose to give it."]},{"heading":"How we use it","body":["To confirm, deliver and support your order.","We send marketing emails only if you opt in, and you can unsubscribe at any time."]},{"heading":"Who we share it with","body":["Only the courier company delivering your parcel. We never sell customer information."]}]},"terms":{"title":"Terms and conditions","intro":"The basics of ordering from Candle Lit Studio.","sections":[{"heading":"Orders","body":["An order is confirmed once we have verified it with you by phone or WhatsApp.","We may cancel orders we cannot verify, or that we cannot fulfil because of stock."]},{"heading":"Prices","body":["All prices are in Pakistani Rupees and include applicable taxes. Delivery is shown separately at checkout."]},{"heading":"Payment","body":["Every order is paid by Easypaisa before it is sent. At checkout you see our Easypaisa number and the exact amount, delivery included.","Add the transaction ID and a screenshot when you place your order. We check each payment by hand and confirm your order once it reaches us. If something does not match, we email you and you can send the correct details from your order page."]}]}}'::jsonb),
  ('care', '{"steps":[{"title":"Let the first burn reach the edges","body":"Burn a new candle until the whole surface has melted, usually 2 to 3 hours. This stops it tunnelling down the middle later."},{"title":"Trim the wick to 5 mm","body":"Before every burn, pinch or cut off the blackened tip. A short wick gives a steady flame and keeps the jar clean."},{"title":"Burn for no more than 4 hours","body":"Put the candle out, let it cool and set, then trim the wick before you light it again."},{"title":"Stop at the last centimetre","body":"When 1 cm of wax is left, retire the candle. Wash the jar in warm soapy water and reuse it."}],"safety":["Never leave a burning candle unattended.","Keep it away from curtains, children and pets.","Place it on a flat, heat-resistant surface.","Keep the wax pool free of matches and wick trimmings."]}'::jsonb),
  ('about', '{"title":["Made slowly, in a small","room in Quetta."],"intro":"One maker, a few helping hands and a shelf of fragrance oils. We pour candles that smell like the places we come from.","storyHeading":"How it began","story":["It started with a gift. A friend was moving abroad and wanted something that smelled like home. Nothing in the shops came close, so the first Desi Gulab candle was poured in a steel pot on a kitchen stove.","She asked for six more. Then her cousins did. The stove became a workbench, the workbench became a studio, and the list of fragrances grew: chai on a cold morning, motia after dark, the first rain on dry earth.","We are still small on purpose. Small batches mean we can test every pour, trim every wick and write your gift note by hand."],"processHeading":"How a candle is made","process":[{"title":"Melt","text":"Soy wax is melted slowly to 80°C in batches of forty candles."},{"title":"Blend","text":"Fragrance oil is stirred in by hand for two full minutes so it binds with the wax."},{"title":"Pour","text":"Each jar is wicked, centred and poured, then left untouched overnight."},{"title":"Cure","text":"Candles rest for two weeks before they are sold. That is what makes the scent carry."}],"closing":"Somewhere on the shelf is the one that smells like home."}'::jsonb),
  ('testimonials', '[{"quote":"I have tried imported candles at four times the price. These burn cleaner, and they smell like home.","author":"Ayesha K.","city":"Lahore"},{"quote":"Ordered on Monday, paid at the door on Wednesday. Every jar was wrapped so well that nothing moved in the box.","author":"Bilal R.","city":"Karachi"},{"quote":"Chai & Cardamom is now the smell of our winter. My children ask me to light it after school.","author":"Maham T.","city":"Faisalabad"}]'::jsonb),
  ('social', '{"instagram":"https://instagram.com/candlelitstudio","facebook":"https://facebook.com/candlelitstudio","tiktok":""}'::jsonb),
  ('seo', '{"title":"Candle Lit Studio | Hand-poured candles, delivered across Pakistan","description":"Hand-poured soy candles from Quetta, in scents that feel like home: desi gulab, chai and cardamom, motia and oud. Delivered across Pakistan."}'::jsonb)
